-- CHAMBA 047 — Agenda técnico rápida (evita timeout PostgREST + login teléfono)-- get_worker_agenda_panel: payload liviano, LIMIT 40, sin to_jsonb(j.*)-- get_worker_assignments: misma lógica optimizada (compat)SET statement_timeout = '120s';CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_worker_agenda_panel CASCADE;CREATE OR REPLACE FUNCTION get_worker_agenda_panel(p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_result JSONB;BEGIN  IF p_worker_id IS NULL THEN    RETURN '[]'::jsonb;  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_worker_id AND p.role::text = 'worker'  ) THEN    RETURN '[]'::jsonb;  END IF;  IF auth.uid() IS NOT NULL AND auth.uid() <> p_worker_id THEN    IF NOT EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    ) THEN      RETURN '[]'::jsonb;    END IF;  END IF;  SELECT COALESCE(    jsonb_agg(row_payload ORDER BY assigned_at DESC),    '[]'::jsonb  )  INTO v_result  FROM (    SELECT      ja.assigned_at,      jsonb_build_object(        'id', ja.id,        'job_id', ja.job_id,        'worker_id', ja.worker_id,        'assigned_at', ja.assigned_at,        'completed_at', ja.completed_at,        'payment_status', ja.payment_status,        'payment_intent_id', ja.payment_intent_id,        'selection_status', ja.selection_status,        'job', jsonb_build_object(          'id', j.id,          'title', j.title,          'description', j.description,          'category', j.category,          'status', j.status,          'operational_phase', j.operational_phase,          'pay_amount', j.pay_amount,          'worker_payout', j.worker_payout,          'platform_fee', j.platform_fee,          'duration_hours', j.duration_hours,          'created_by', j.created_by,          'assigned_worker_id', j.assigned_worker_id,          'address', j.address,          'lat', j.lat,          'lng', j.lng,          'created_at', j.created_at,          'updated_at', j.updated_at        )      ) AS row_payload    FROM job_assignments ja    INNER JOIN jobs j ON j.id = ja.job_id    WHERE ja.worker_id = p_worker_id      AND NOT (        ja.selection_status = 'rejected'        AND j.status::text IN ('taken', 'in_progress', 'completed', 'cancelled')      )    ORDER BY ja.assigned_at DESC    LIMIT 40  ) sub;  RETURN v_result;END;$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_worker_assignments CASCADE;CREATE OR REPLACE FUNCTION get_worker_assignments(p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$BEGIN  RETURN get_worker_agenda_panel(p_worker_id);END;$$;GRANT EXECUTE ON FUNCTION get_worker_agenda_panel(UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION get_worker_assignments(UUID) TO anon, authenticated;